/* the screen wall's pictures for this work (see the router script): kept as data so the WebGL wall is never blocked by a cross-origin rule */
(function (D) {
  D['moment:0'] = 'data:image/webp;base64,';
  D['moment:1'] = 'data:image/webp;base64,';
  D['moment:2'] = 'data:image/webp;base64,';
  D['moment:3'] = 'data:image/webp;base64,';
  D['moment:4'] = 'data:image/webp;base64,';
  D['moment:5'] = 'data:image/webp;base64,';
  D['moment:6'] = 'data:image/webp;base64,';
  D['moment:full'] = 'data:image/webp;base64,';
  D['#moment'] = 1;
})(window.AppLData = window.AppLData || {});
